Visitas por socio con fecha de corte `2026-10-01`. Datos **distintos**:

```sql
CREATE TABLE socios (id INTEGER PRIMARY KEY, nombre VARCHAR(20));
INSERT INTO socios VALUES (1,'Ana'),(2,'Luis'),(3,'Eva');
CREATE TABLE visitas (id INTEGER PRIMARY KEY, socio_id INTEGER, dia DATE);
INSERT INTO visitas VALUES (1,1,'2026-09-29'),(2,1,'2026-09-20'),(3,2,'2026-08-01');

SELECT s.id,
       DATE '2026-10-01' - MAX(v.dia) AS dias_desde_ultima,   -- Recencia
       COUNT(v.id)                    AS visitas              -- Frecuencia (0 si no hay)
FROM socios s
LEFT JOIN visitas v ON v.socio_id = s.id                       -- Eva (sin visitas) se conserva
GROUP BY s.id
ORDER BY s.id;
-- (1, 2, 2) · (2, 61, 1) · (3, NULL, 0)
```
